    public int compare(anytype o1, anytype o2)
    {
        GUPPriceEngineMarginCodeLineAggregation obj1 = o1;
        GUPPriceEngineMarginCodeLineAggregation obj2 = o2;

        // Sort by priority in descending order.
        if (obj1.parmLinePriority() != obj2.parmLinePriority())
        {
            return obj2.parmLinePriority() - obj1.parmLinePriority();
        }

        // Sort by adjustment (percentage) in ascending order.
        if (obj1.parmLowestPercentage() > obj2.parmLowestPercentage())
        {
            return 1;
        }
        else if (obj1.parmLowestPercentage() < obj2.parmLowestPercentage())
        {
            return -1;
        }
        return 0;
    }
